 static void Garland(Transform p,Vector3 a,Vector3 b,int count){var previous=a;for(int i=0;i<=count;i++){float f=i/(float)count;var q=Vector3.Lerp(a,b,f)-Vector3.up*Mathf.Sin(f*Mathf.PI)*.65f;Shape("Warm_Festive_Bulb",p,PrimitiveType.Sphere,q,Vector3.one*.3f,i%3==0?red:bulb);if(i>0){var delta=q-previous;var o=Shape("Garland_Cord",p,PrimitiveType.Cube,(q+previous)*.5f,new Vector3(.045f,.045f,delta.magnitude),dark);o.localRotation=Quaternion.LookRotation(delta);}previous=q;}}
 static string Fingerprint(GameObject o){return string.Join("\n",o.GetComponentsInChildren<MonoBehaviour>(true).Where(c=>c).Select(c=>c.GetType().FullName+":"+EditorJsonUtility.ToJson(c)))+"\nCOLLIDERS="+string.Join(";",o.GetComponentsInChildren<Collider>(true).Select(c=>EditorJsonUtility.ToJson(c)));}
 static void Batch(Transform category){var filters=category.GetComponentsInChildren<MeshFilter>().Where(m=>m.GetComponent<MeshRenderer>()!=null&&m.gameObject.activeInHierarchy).ToArray();var batches=new Dictionary<Material,List<CombineInstance>>();foreach(var mf in filters){var r=mf.GetComponent<MeshRenderer>();for(int i=0;i<mf.sharedMesh.subMeshCount;i++){var mat=r.sharedMaterials[Math.Min(i,r.sharedMaterials.Length-1)];if(!batches.ContainsKey(mat))batches[mat]=new List<CombineInstance>();batches[mat].Add(new CombineInstance{mesh=mf.sharedMesh,subMeshIndex=i,transform=category.worldToLocalMatrix*mf.transform.localToWorldMatrix});}}var children=category.Cast<Transform>().ToArray();foreach(var kv in batches){var m=new Mesh();m.name=category.name+"_"+kv.Key.name;m.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;m.CombineMeshes(kv.Value.ToArray(),true,true);AssetDatabase.CreateAsset(m,D+"/"+m.name+".asset");var node=Node(m.name,category,Vector3.zero);node.gameObject.AddComponent<MeshFilter>().sharedMesh=m;node.gameObject.AddComponent<MeshRenderer>().sharedMaterial=kv.Key;}foreach(var t in children)UnityEngine.Object.DestroyImmediate(t.gameObject);}
 static float Ground(float x,float z){float best=float.NegativeInfinity;foreach(var t in ground){var a=t[0];var b=t[1];var c=t[2];float den=(b.z-c.z)*(a.x-c.x)+(c.x-b.x)*(a.z-c.z);if(Mathf.Abs(den)<.00001f)continue;float u=((b.z-c.z)*(x-c.x)+(c.x-b.x)*(z-c.z))/den;float v=((c.z-a.z)*(x-c.x)+(a.x-c.x)*(z-c.z))/den;if(u>=-.001f&&v>=-.001f&&u+v<=1.001f)best=Mathf.Max(best,u*a.y+v*b.y+(1-u-v)*c.y);}if(float.IsNegativeInfinity(best))throw new Exception("No ground at "+x+","+z);return best;}
 static void Drift(Transform p,Vector3 pos,Vector3 size){float y=Ground(pos.x,pos.z);pos.y=y+size.y*.5f-.055f;Shape("Grounded_Snowdrift",p,PrimitiveType.Sphere,pos,size,snow);audit.Add("snow x="+pos.x+" z="+pos.z+" ground="+y+" bottom="+(pos.y-size.y*.5f));patches++;}
 static void Line(Transform p,Vector3 a,Vector3 b){float len=Vector3.Distance(a,b);int count=Mathf.Max(2,Mathf.CeilToInt(len/.7f));var delta=b-a;var cord=Shape("Roof_Cord",p,PrimitiveType.Cube,(a+b)*.5f,new Vector3(.055f,.055f,len),dark);cord.localRotation=Quaternion.LookRotation(delta);for(int i=0;i<=count;i++)Shape("Roof_Light",p,PrimitiveType.Sphere,Vector3.Lerp(a,b,i/(float)count),Vector3.one*.24f,i%4==0?red:bulb);}
 static void Cone(Transform p,Vector3 pos,float radius,float length){int n=10;var v=new List<Vector3>();for(int i=0;i<n;i++)v.Add(new Vector3(Mathf.Cos(i*2*Mathf.PI/n)*radius,Mathf.Sin(i*2*Mathf.PI/n)*radius,0));v.Add(Vector3.forward*length);v.Add(Vector3.zero);var tr=new List<int>();for(int i=0;i<n;i++){int j=(i+1)%n;tr.AddRange(new[]{i,j,n,n+1,j,i});}var m=new Mesh();m.SetVertices(v);m.SetTriangles(tr,0);m.RecalculateNormals();var g=Node("Pointed_Carrot",p,pos);g.gameObject.AddComponent<MeshFilter>().sharedMesh=m;g.gameObject.AddComponent<MeshRenderer>().sharedMaterial=orange;}
 static void Bucket(Transform g){int n=12;var vs=new List<Vector3>();for(int j=0;j<2;j++)for(int i=0;i<n;i++){float a=i*2*Mathf.PI/n;float r=j==0?.58f:.42f;vs.Add(new Vector3(Mathf.Cos(a)*r,2.92f+j*.58f,Mathf.Sin(a)*r));}vs.Add(new Vector3(0,3.50f,0));var tr=new List<int>();for(int i=0;i<n;i++){int j=(i+1)%n;tr.AddRange(new[]{i,n+j,j,i,n+i,n+j,n+i,2*n,n+j});}var m=new Mesh();m.SetVertices(vs);m.SetTriangles(tr,0);m.RecalculateNormals();var o=Node("Metal_Bucket",g,Vector3.zero);o.gameObject.AddComponent<MeshFilter>().sharedMesh=m;o.gameObject.AddComponent<MeshRenderer>().sharedMaterial=metal;Shape("Bucket_Rim",g,PrimitiveType.Cylinder,new Vector3(0,2.94f,0),new Vector3(1.2f,.045f,1.2f),metal);for(int i=0;i<10;i++){float a=i*Mathf.PI/10,b=(i+1)*Mathf.PI/10;var p1=new Vector3(Mathf.Cos(a)*.64f,3.15f+Mathf.Sin(a)*.65f,0);var p2=new Vector3(Mathf.Cos(b)*.64f,3.15f+Mathf.Sin(b)*.65f,0);var h=Shape("Bucket_Handle",g,PrimitiveType.Cube,(p1+p2)*.5f,new Vector3(.035f,.035f,(p2-p1).magnitude),dark);h.localRotation=Quaternion.LookRotation(p2-p1);}}
 public static string Main(){if(AssetDatabase.IsValidFolder(D))throw new Exception("Already built");Directory.CreateDirectory(D);AssetDatabase.Refresh();snow=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/Snow.mat");red=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/Ruby.mat");gold=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/Gold.mat");green=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/Fir.mat");dark=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/WinterTown169/Charcoal.mat");orange=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/WinterTown169/Carrot.mat");bulb=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/WinterTown169/Warm_Light.mat");metal=new Material(snow);metal.color=new Color(.42f,.48f,.53f);if(metal.HasProperty("_Metallic"))metal.SetFloat("_Metallic",.4f);AssetDatabase.CreateAsset(metal,D+"/Bucket_Metal.mat");wraps=new[]{red,green,gold};var path="Assets/Events/NewYear/NY_Castle.prefab";var o=PrefabUtility.LoadPrefabContents(path);try{root=o.transform;var fingerprint=Fingerprint(o);
 foreach(var mf in root.Find("Visual").GetComponentsInChildren<MeshFilter>()){if(mf.sharedMesh==null)continue;var v=mf.sharedMesh.vertices;var tt=mf.sharedMesh.triangles;for(int i=0;i<tt.Length;i+=3){var a=root.InverseTransformPoint(mf.transform.TransformPoint(v[tt[i]]));var b=root.InverseTransformPoint(mf.transform.TransformPoint(v[tt[i+1]]));var c=root.InverseTransformPoint(mf.transform.TransformPoint(v[tt[i+2]]));if(Mathf.Max(a.y,b.y,c.y)>.8f||Mathf.Min(a.y,b.y,c.y)<-.5f)continue;if(Mathf.Abs(Vector3.Cross(b-a,c-a).y)<.01f)continue;ground.Add(new[]{a,b,c});}}
