 foreach(var name in new[]{"WinterTown_169/Trees_Gifts","WinterTown_169/Snowmen","WinterTown_169/Garlands","WinterTown_169/Garland_Supports","WinterTown_170_Additions/Inner_Wall_Decor","WinterTown_170_Additions/Rounded_Snowdrifts"}){var t=root.Find(name);if(t)t.gameObject.SetActive(false);}
 // Keep roof snow, remove old ground triangles and replace with explicitly grounded drifts.
 var oldSnow=root.Find("WinterTown_169/Snow").GetComponentsInChildren<MeshFilter>().Single(m=>m.sharedMesh.name=="Snow_Snow");var roof=UnityEngine.Object.Instantiate(oldSnow.sharedMesh);var vv=roof.vertices;var oldTr=roof.triangles;var keep=new List<int>();for(int i=0;i<oldTr.Length;i+=3)if(vv[oldTr[i]].y>2||vv[oldTr[i+1]].y>2||vv[oldTr[i+2]].y>2)keep.AddRange(new[]{oldTr[i],oldTr[i+1],oldTr[i+2]});roof.triangles=keep.ToArray();roof.name="Roof_Snow_Only";roof.RecalculateBounds();AssetDatabase.CreateAsset(roof,D+"/RoofSnowOnly.asset");oldSnow.sharedMesh=roof;
 deco=Node("WinterTown_171",root,Vector3.zero);var snowGroup=Node("Grounded_Snow",deco,Vector3.zero);var ts=Node("Scattered_Snowy_Firs",deco,Vector3.zero);var men=Node("Bucket_Snowmen",deco,Vector3.zero);var lights=Node("House_Roof_Lights",deco,Vector3.zero);
 var positions=new[]{new Vector3(-18,0,-43),new Vector3(-15,0,-5),new Vector3(-19,0,24),new Vector3(-16,0,43),new Vector3(20,0,-39),new Vector3(16,0,-12),new Vector3(19,0,13),new Vector3(15,0,39),new Vector3(-35,0,-7),new Vector3(35,0,18)};
 foreach(var pos in positions){float height=6.5f+(float)rng.NextDouble()*3.5f;var fir=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Events/NewYear/NY_FestiveFir.prefab"),ts);fir.transform.localPosition=Vector3.zero;fir.transform.localRotation*=Quaternion.Euler(0,(float)rng.NextDouble()*360,0);var b=LocalBounds(fir.transform);fir.transform.localScale*=height/b.size.y;b=LocalBounds(fir.transform);fir.transform.localPosition+=new Vector3(pos.x,Ground(pos.x,pos.z),pos.z)-new Vector3(b.center.x,b.min.y,b.center.z);foreach(var col in fir.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(col);
 var verts=new List<Vector3>();var tr=new List<int>();foreach(var mf in fir.GetComponentsInChildren<MeshFilter>()){var rr=mf.GetComponent<MeshRenderer>();if(rr.sharedMaterials.All(m=>m.name!="Color_003"&&!m.name.ToLower().Contains("green")&&!m.name.ToLower().Contains("fir"))&&mf.transform.IsChildOf(fir.transform.Find("NewYear_Decoration")))continue;if(mf.transform.IsChildOf(fir.transform.Find("NewYear_Decoration")))continue;var mesh=mf.sharedMesh;var v=mesh.vertices;var ns=mesh.normals;var inds=mesh.triangles;for(int i=0;i<inds.Length;i+=3){var a=root.InverseTransformPoint(mf.transform.TransformPoint(v[inds[i]]));var bb=root.InverseTransformPoint(mf.transform.TransformPoint(v[inds[i+1]]));var c=root.InverseTransformPoint(mf.transform.TransformPoint(v[inds[i+2]]));var n=mf.transform.TransformDirection(ns[inds[i]]+ns[inds[i+1]]+ns[inds[i+2]]).normalized;if(n.y<.2f||Mathf.Min(a.y,bb.y,c.y)<Ground(pos.x,pos.z)+height*.2f||i%9==0)continue;var center=(a+bb+c)/3;int k=verts.Count;verts.Add(center+(a-center)*.77f+n*.035f);verts.Add(center+(bb-center)*.77f+n*.035f);verts.Add(center+(c-center)*.77f+n*.035f);tr.AddRange(new[]{k,k+1,k+2});}}
 var sm=new Mesh();sm.SetVertices(verts);sm.SetTriangles(tr,0);sm.RecalculateNormals();var patch=Node("Snow_On_Branches",ts,Vector3.zero);patch.gameObject.AddComponent<MeshFilter>().sharedMesh=sm;patch.gameObject.AddComponent<MeshRenderer>().sharedMaterial=snow;trees++;for(int j=0;j<3;j++)Drift(snowGroup,pos+new Vector3((j-1)*1.6f,0,j%2==0?-.8f:1),new Vector3(6.2f-j*.5f,.7f+j*.27f,5.5f));Gift(ts,new Vector3(pos.x+2.6f,Ground(pos.x+2.6f,pos.z),pos.z),.8f);}
 foreach(int side in new[]{-1,1}){for(int i=0;i<17;i++)Drift(snowGroup,new Vector3(side*(13.7f+(float)rng.NextDouble()),0,-49+i*6),new Vector3(3,.25f+(float)rng.NextDouble()*.35f,4.5f));foreach(float z in new[]{-40f,-27f,-14f,0f,13f,30f,40f})Drift(snowGroup,new Vector3(side*47.2f,0,z),new Vector3(5.6f,.65f+(float)rng.NextDouble()*.8f,6));foreach(float z in new[]{-8f,18f})Drift(snowGroup,new Vector3(side*34,0,z),new Vector3(11,1.2f,5));foreach(float z in new[]{-37f,-2f,25f,48f}){var pos=new Vector3(side*20,Ground(side*20,z),z);var g=Node("Bucket_Snowman",men,pos);g.localRotation=Quaternion.Euler(0,side<0?90:-90,0);Shape("Body",g,PrimitiveType.Sphere,new Vector3(0,.75f,0),new Vector3(1.8f,1.6f,1.65f),snow);Shape("Chest",g,PrimitiveType.Sphere,new Vector3(0,1.65f,0),new Vector3(1.35f,1.25f,1.3f),snow);Shape("Head",g,PrimitiveType.Sphere,new Vector3(0,2.45f,0),Vector3.one*1.05f,snow);Shape("Scarf",g,PrimitiveType.Cylinder,new Vector3(0,2.05f,0),new Vector3(1.2f,.12f,1.2f),red);Shape("Scarf_Tail",g,PrimitiveType.Cube,new Vector3(.3f,1.65f,.62f),new Vector3(.24f,.7f,.1f),red);foreach(float x in new[]{-.18f,.18f})Shape("Eye",g,PrimitiveType.Sphere,new Vector3(x,2.55f,.48f),Vector3.one*.12f,dark);for(int i=0;i<3;i++)Shape("Button",g,PrimitiveType.Sphere,new Vector3(0,1.65f-i*.3f,.68f),Vector3.one*.13f,dark);Cone(g,new Vector3(0,2.4f,.49f),.13f,.65f);Bucket(g);snowmen++;}}
 int houses=0;foreach(Transform house in root){if(house.name=="Visual"||house.name.StartsWith("WinterTown")||house.name.StartsWith("NewYear")||house.name=="Collider"||house.name=="EntryTrigger")continue;var roofs=house.GetComponentsInChildren<MeshFilter>().Where(m=>m.GetComponent<MeshRenderer>()&&m.GetComponent<MeshRenderer>().sharedMaterials.Any(mat=>mat&&mat.name.Contains("Color_B08"))).OrderByDescending(m=>LocalBounds(m.transform).size.x*LocalBounds(m.transform).size.z).ToArray();if(roofs.Length==0)continue;var bounds=LocalBounds(roofs[0].transform);float y=bounds.min.y+.18f,top=bounds.max.y+.15f,x1=bounds.min.x-.14f,x2=bounds.max.x+.14f,z1=bounds.min.z-.14f,z2=bounds.max.z+.14f,zc=bounds.center.z;var a=new Vector3(x1,y,z1);var b=new Vector3(x2,y,z1);var c=new Vector3(x1,y,z2);var d=new Vector3(x2,y,z2);var r1=new Vector3(x1,top,zc);var r2=new Vector3(x2,top,zc);Line(lights,a,b);Line(lights,c,d);Line(lights,a,r1);Line(lights,r1,c);Line(lights,b,r2);Line(lights,r2,d);houses++;}
 if(houses!=6)throw new Exception("Expected six roof outlines, got "+houses);foreach(var cat in new[]{snowGroup,ts,men,lights})Batch(cat);if(Fingerprint(o)!=fingerprint)throw new Exception("Gameplay/colliders changed");PrefabUtility.SaveAsPrefabAsset(o,path);AssetDatabase.SaveAssets();audit.Add("trees="+trees+" snowmen="+snowmen+" groundedDrifts="+patches+" roofOutlines="+houses+" groundTriangles="+ground.Count);File.WriteAllLines("Docs/locations/previews/winter-town171-ground-check.txt",audit);return audit.Last()+"; gameplay fingerprint unchanged; old wall decorations, tree rows and hats disabled.";}finally{PrefabUtility.UnloadPrefabContents(o);}}
